PRAGMA foreign_keys = ON;

-- Forward migration: add staged retrieval exercises without rewriting user attempts.
ALTER TABLE pl_lesson_steps ADD COLUMN question_type TEXT NOT NULL DEFAULT 'free_input';
ALTER TABLE pl_lesson_steps ADD COLUMN direction TEXT NOT NULL DEFAULT 'meaning_to_polish';
ALTER TABLE pl_lesson_steps ADD COLUMN answer_text TEXT DEFAULT '';
ALTER TABLE pl_lesson_steps ADD COLUMN cloze_prefix TEXT NOT NULL DEFAULT '';
ALTER TABLE pl_lesson_steps ADD COLUMN cloze_suffix TEXT NOT NULL DEFAULT '';
ALTER TABLE pl_lesson_steps ADD COLUMN cloze_answer TEXT NOT NULL DEFAULT '';
ALTER TABLE pl_lesson_steps ADD COLUMN tokens_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE pl_lesson_steps ADD COLUMN scaffold_level INTEGER NOT NULL DEFAULT 2;
ALTER TABLE pl_lesson_steps ADD COLUMN hint_text TEXT NOT NULL DEFAULT '';

ALTER TABLE pl_attempts ADD COLUMN step_id TEXT REFERENCES pl_lesson_steps(id);
ALTER TABLE pl_attempts ADD COLUMN question_type TEXT NOT NULL DEFAULT 'free_input';
ALTER TABLE pl_attempts ADD COLUMN direction TEXT NOT NULL DEFAULT 'meaning_to_polish';
ALTER TABLE pl_attempts ADD COLUMN difficulty_before INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_attempts ADD COLUMN difficulty_after INTEGER NOT NULL DEFAULT 0;

ALTER TABLE pl_review_states ADD COLUMN difficulty_level INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_review_states ADD COLUMN success_streak INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_review_states ADD COLUMN failure_streak INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_review_states ADD COLUMN last_question_type TEXT;
ALTER TABLE pl_review_states ADD COLUMN last_direction TEXT;

CREATE TABLE IF NOT EXISTS pl_review_events (
  id TEXT PRIMARY KEY,
  profile_id TEXT NOT NULL REFERENCES pl_profiles(id),
  item_id TEXT NOT NULL REFERENCES pl_learning_items(id),
  attempt_id TEXT REFERENCES pl_attempts(id),
  rating TEXT NOT NULL CHECK (rating IN ('again', 'hard', 'good', 'easy')),
  question_type TEXT NOT NULL CHECK (question_type IN ('multiple_choice', 'cloze', 'unscramble', 'free_input')),
  direction TEXT NOT NULL CHECK (direction IN ('meaning_to_polish', 'polish_to_meaning')),
  was_correct INTEGER NOT NULL CHECK (was_correct IN (0, 1)),
  difficulty_before INTEGER NOT NULL,
  difficulty_after INTEGER NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pl_review_events_profile_created ON pl_review_events(profile_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pl_review_events_item_created ON pl_review_events(profile_id, item_id, created_at DESC);

