-- Backfill and indexes make the migration safe for the already-created Unit 1 rows.
-- The original Unit 1 item ids predate this migration, so resolve by item_id rather
-- than relying on the generated legacy aliases in the staged update statements.
UPDATE pl_lesson_steps
SET answer_text = CASE
  WHEN question_type = 'multiple_choice' AND direction = 'polish_to_meaning'
    THEN (SELECT meaning_ja FROM pl_learning_items i WHERE i.id = pl_lesson_steps.item_id)
  ELSE (SELECT polish FROM pl_learning_items i WHERE i.id = pl_lesson_steps.item_id)
END
WHERE answer_text IS NULL OR answer_text = '';
CREATE INDEX IF NOT EXISTS idx_pl_steps_question_type ON pl_lesson_steps(question_type, scaffold_level);
CREATE INDEX IF NOT EXISTS idx_pl_reviews_difficulty ON pl_review_states(profile_id, difficulty_level, due_at);
